import subprocess

def delta(inp):
    p=subprocess.run(["./executable","--no-gitconfig","--paging","never"], input=inp.encode(), stdout=subprocess.PIPE)
    return p.stdout.decode(errors='replace')

for start in [1,9,10,99,100,1000]:
    diff=f"diff --git a/f b/f\n--- a/f\n+++ b/f\n@@ -{start},1 +{start},1 @@\n-a\n+b\n"
    out=delta(diff)
    # extract hunk header lines
    lines=out.splitlines()
    # find lines containing "─┐"
    for l in lines:
        if "┐" in l:
            # strip ansi
            import re
            clean=re.sub(r'\x1b\[[0-9;]*m','',l)
            print(f"start={start} header line={repr(clean)} len={len(clean)}")
            break
    # also find line number line
    for l in lines:
        if re.search(r'\d+.*│', re.sub(r'\x1b\[[0-9;]*m','',l)):
            clean=re.sub(r'\x1b\[[0-9;]*m','',l)
            if clean.strip().startswith(str(start)) or "│" in clean:
                # but earlier header number line is like "1: │"
                pass
    # print full
    print("Full out for start",start, repr(out.replace("\x1b","\\x1b")[:800]))
    print("---")
