    if possible:
        msg += f"  [possible values: \x1b[32m" + "\x1b[0m, \x1b[32m".join(possible) + "\x1b[0m]\n"
        msg += "\nFor more information, try '\x1b[1m--help\x1b[0m'.\n"
    else:
        msg += "\nFor more information, try '\x1b[1m--help\x1b[0m'.\n"
    eprint(msg, 2)

