def parse_width(value):
    # Implements logic matching original
    if value == "variable":
        return "variable"
    # Handle leading dash (e.g., "-2")
    if value.startswith("-"):
        # should be negative integer
        try:
            n = int(value)
            # Assume terminal width 80
            return str(80 + n)
        except:
            eprint(f'Invalid value for width: "{value}" is not an integer\n', 2)
    if "-" in value:
        idx = value.find("-")
        left_str = value[:idx]
        right_str = value[idx:]  # includes dash
        # left must be integer
        try:
            left = int(left_str)
        except:
            eprint(f'Invalid value for width: "{left_str}" (from "{value}") is not an integer\n', 2)
        # right must be negative integer
        try:
            right = int(right_str)
            if right >= 0:
                raise ValueError
        except:
            eprint(f'Invalid value for width: "{right_str}" (from "{value}") is not a negative integer\n', 2)
        return str(left + right)
    # plain integer
    try:
        n = int(value)
        return str(n)
    except:
        eprint(f'Invalid value for width: "{value}" is not an integer\n', 2)

